package com.menstyle.entity;
import com.menstyle.entity.enums.DiscountType; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Getter @Setter @NoArgsConstructor @Entity @Table(name="coupons",uniqueConstraints=@UniqueConstraint(name="uk_coupons_code",columnNames="code"),indexes=@Index(name="idx_coupons_code",columnList="code"))
public class Coupon extends BaseEntity { @Column(nullable=false,length=50) private String code; @Column(nullable=false,length=150) private String name; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private DiscountType discountType; @Column(nullable=false,precision=19,scale=2) private BigDecimal discountValue; @Column(nullable=false,precision=19,scale=2) private BigDecimal minimumOrder; private BigDecimal maximumDiscount; private Integer usageLimit; private Integer usageLimitPerUser; private LocalDateTime startAt; private LocalDateTime endAt; @Column(nullable=false) private boolean status; }
